20.71 Conexión con R


Código
library(keras)

modelo &lt;- keras_model_sequential() |&gt;
  layer_dense(
    units = 16,
    activation = "relu",
    input_shape = 4
  ) |&gt;
  layer_dropout(rate = 0.2) |&gt;
  layer_dense(
    units = 8,
    activation = "relu"
  ) |&gt;
  layer_dense(
    units = 1,
    activation = "sigmoid"
  )

modelo |&gt;
  compile(
    optimizer = optimizer_adam(
      learning_rate = 0.001
    ),
    loss = "binary_crossentropy",
    metrics = c("accuracy")
  )

historial &lt;- modelo |&gt;
  fit(
    x = x_entrenamiento,
    y = y_entrenamiento,
    epochs = 100,
    batch_size = 32,
    validation_split = 0.2,
    callbacks = list(
      callback_early_stopping(
        patience = 10,
        restore_best_weights = TRUE
      )
    )
  )

predict(modelo, x_prueba)

